pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 100 ether);
        vm.deal(address(this), amount);
        // Call addToBalance() which uses the nonReentrant_ modifier
        c.addToBalance{value: amount}();
        // After the call, the reentrancy lock must be released.
        // Since locked_ is private we cannot read it directly.
        // The rule: calling addToBalance again should succeed (not revert due to lock).
        // We attempt the same call again; if locked_ were still true, it would revert on require(!locked_).
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("addToBalance()"));
        assertTrue(success, "Reentrancy lock should be released after addToBalance");
    }
}

