pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, address(this).balance);

        // Record state before
        uint256 callerBalanceBefore = caller.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Perform addToBalance via caller
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("addToBalance()"));
        vm.assume(success);

        // Record state after
        uint256 callerBalanceAfter = caller.balance;
        uint256 contractBalanceAfter = address(c).balance;

        // General rule: total sum (caller + contract) increases by exactly msg.value
        uint256 sumBefore = callerBalanceBefore + contractBalanceBefore;
        uint256 sumAfter = callerBalanceAfter + contractBalanceAfter;
        assertTrue(sumAfter == sumBefore + amount, "total balance invariant broken");
    }
}

