pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 amount) public {
        vm.assume(user != address(0));
        vm.assume(user != address(c));
        amount = bound(amount, 1, 100 ether);

        // fund user and send to contract via addToBalance
        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();

        uint256 balanceBefore = address(c).balance;

        // user tries to withdraw
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawBalance.selector));

        if (success) {
            // In reference, balance after withdraw is 0; in buggy version, balance remains unchanged (amount)
            assertTrue(address(c).balance == 0, "Withdraw should empty balance");
        } else {
            // If revert, it should be because of the bug (self-call with 0 gas), amount stays
            assertTrue(address(c).balance == balanceBefore, "Revert should keep balance unchanged");
        }
    }
}

