pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        amount = bound(amount, 1, 1e30);

        uint256 beforeContractBalance = address(c).balance;

        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();

        uint256 afterAddBalance = address(c).balance;

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));

        uint256 afterWithdrawBalance = address(c).balance;

        // General rule: after the sequence, the contract balance is either unchanged from after addToBalance (if withdrawal fails) 
        // or back to what it was before addToBalance (if withdrawal succeeds).
        // In the buggy mutant, the withdrawal always fails, but the contract still sets userBalance to 0, preventing further withdrawals.
        // The key invariant is that the contract balance never increases after a withdraw attempt.
        assertTrue(afterWithdrawBalance <= afterAddBalance && afterWithdrawBalance >= beforeContractBalance);
    }
}

